// Change LIMIT identically for every tool when comparing workload sizes.
const LIMIT = 100000;

function countPrimes(limit: number): number {
  let count = 0;
  for (let candidate = 2; candidate <= limit; candidate++) {
    let prime = true;
    for (let divisor = 2; divisor * divisor <= candidate; divisor++) {
      if (candidate % divisor === 0) {
        prime = false;
        break;
      }
    }
    if (prime) count++;
  }
  return count;
}

return countPrimes(LIMIT);
}

var durations: number[] = [];
var result;
for (var sample = 0; sample < 7; sample++) {
  var start = Date.now();
  for (var iteration = 0; iteration < 30; iteration++) {
    result = benchmarkWorkload();
  }
  durations.push(Date.now() - start);
}
console.log(JSON.stringify({durations: durations, result: result}));

